8	export async function row_count_matches_source(ctx: AssertionContext): Promise<AssertionResult> {
9	  const pgResult = await ctx.pg.query("SELECT count(*) AS n FROM app.sales");
10	  const sourceCount = Number(pgResult.rows[0]?.n ?? 0);
11	
12	  const chRows = await queryRows<{ n: number }>(
13	    ctx,
14	    "SELECT count() AS n FROM analytics.sales",
15	  );
16	  const targetCount = Number(chRows[0]?.n ?? 0);
17	
18	  const passed = targetCount === sourceCount;
19	  return {
20	    passed,
21	    message: passed
22	      ? `Row count matches: source=${sourceCount}, target=${targetCount}.`
23	      : `Source ${sourceCount}, target ${targetCount}.`,
24	    details: { sourceCount, targetCount },
25	  };
26	}
