1	import { readdirSync, readFileSync, statSync } from "node:fs";
2	import { basename, extname, join } from "node:path";
3	
4	import type { AssertionResult } from "@dec-bench/eval-core";
5	
6	const WORKSPACE_ROOT = "/workspace";
7	const IGNORED_DIRS = new Set([
8	  ".git",
9	  ".next",
10	  ".turbo",
11	  "dist",
12	  "build",
13	  "coverage",
14	  "node_modules",
15	  "__pycache__",
16	  ".venv",
17	  "venv",
18	]);
19	const TEXT_FILE_EXTENSIONS = new Set([
20	  ".py",
21	  ".js",
22	  ".jsx",
23	  ".ts",
24	  ".tsx",
25	  ".sql",
26	  ".sh",
27	  ".bash",
28	  ".zsh",
29	  ".rb",
30	  ".go",
31	  ".rs",
32	  ".java",
33	  ".yaml",
34	  ".yml",
35	  ".json",
36	  ".toml",
37	  ".ini",
38	  ".cfg",
39	  ".conf",
40	  ".md",
41	]);
42	const DOC_PATHS = [
43	  join(WORKSPACE_ROOT, "README.md"),
44	  join(WORKSPACE_ROOT, "README.txt"),
45	  join(WORKSPACE_ROOT, "docs"),
46	];
47	const DEFAULT_CONNECTION_LITERALS = [
48	  "localhost:5432",
49	  "localhost:8123",
50	  "localhost:9000",
51	  "localhost:9092",
52	];
53	const DEFAULT_ENV_TOKENS = [
54	  "process.env",
55	  "ctx.env(",
56	  "os.environ",
57	  "getenv(",
58	  "POSTGRES_URL",
59	  "CLICKHOUSE_URL",
60	  "REDPANDA_BROKER",
61	];
62	
63	interface WorkspaceTextFile {
64	  path: string;
65	  relativePath: string;
66	  content: string;
67	}
68	
69	export async function scanWorkspaceForHardcodedConnections(options?: {
70	  literals?: string[];
71	  envTokens?: string[];
72	}): Promise<AssertionResult> {
73	  const literals = options?.literals ?? DEFAULT_CONNECTION_LITERALS;
74	  const envTokens = options?.envTokens ?? DEFAULT_ENV_TOKENS;
75	  const findings: Array<{ file: string; line: number; literal: string }> = [];
76	
77	  for (const file of collectWorkspaceTextFiles()) {
78	    const lines = file.content.split(/\r?\n/);
79	    for (let index = 0; index < lines.length; index += 1) {
80	      const line = lines[index] ?? "";
81	      if (!literals.some((literal) => line.includes(literal))) {
82	        continue;
83	      }
84	      if (envTokens.some((token) => line.includes(token))) {
85	        continue;
86	      }
87	      findings.push({
88	        file: file.relativePath,
89	        line: index + 1,
90	        literal: literals.find((literal) => line.includes(literal)) ?? "unknown",
91	      });
92	      if (findings.length >= 10) {
93	        break;
94	      }
95	    }
96	  }
97	
98	  return {
99	    passed: findings.length === 0,
100	    message:
101	      findings.length === 0
102	        ? "No hardcoded connection strings found in workspace files."
103	        : "Hardcoded connection strings found in workspace files.",
104	    details: {
105	      findings,
106	    },
107	  };
108	}
109	
110	export async function hasReadmeOrDocs(): Promise<AssertionResult> {
111	  const foundPaths = DOC_PATHS.filter((path) => exists(path));
112	  return {
113	    passed: foundPaths.length > 0,
114	    message:
115	      foundPaths.length > 0
116	        ? "Workspace includes operator-facing docs or a README."
117	        : "Workspace is missing a README or docs directory for operator handoff.",
118	    details: {
119	      foundPaths,
120	    },
121	  };
122	}
123	
124	export async function avoidsSelectStarQueries(): Promise<AssertionResult> {
125	  const findings: Array<{ file: string; line: number }> = [];
126	  for (const file of collectWorkspaceTextFiles()) {
127	    const lines = file.content.split(/\r?\n/);
128	    for (let index = 0; index < lines.length; index += 1) {
129	      const line = lines[index] ?? "";
130	      if (!/\bselect\s+\*/i.test(line)) {
131	        continue;
132	      }
133	      findings.push({
134	        file: file.relativePath,
135	        line: index + 1,
136	      });
137	      if (findings.length >= 10) {
138	        break;
139	      }
140	    }
141	  }
142	
143	  return {
144	    passed: findings.length === 0,
145	    message:
146	      findings.length === 0
147	        ? "Workspace avoids `SELECT *` queries in checked source files."
148	        : "Workspace still contains `SELECT *` queries in checked source files.",
149	    details: {
150	      findings,
151	    },
152	  };
153	}
154	
155	function collectWorkspaceTextFiles(): WorkspaceTextFile[] {
156	  const files: WorkspaceTextFile[] = [];
157	  const visit = (current: string, relativePrefix = "") => {
158	    for (const entry of readdirSync(current, { withFileTypes: true })) {
159	      if (entry.isDirectory()) {
160	        if (IGNORED_DIRS.has(entry.name)) {
161	          continue;
162	        }
163	        visit(join(current, entry.name), join(relativePrefix, entry.name));
164	        continue;
165	      }
166	      if (!entry.isFile()) {
167	        continue;
168	      }
169	      const extension = extname(entry.name).toLowerCase();
170	      if (!TEXT_FILE_EXTENSIONS.has(extension) && basename(entry.name).toLowerCase() !== "dockerfile") {
171	        continue;
172	      }
173	
174	      const absolutePath = join(current, entry.name);
175	      if (!isReadableTextFile(absolutePath)) {
176	        continue;
177	      }
178	      files.push({
179	        path: absolutePath,
180	        relativePath: join(relativePrefix, entry.name),
181	        content: readFileSync(absolutePath, "utf8"),
182	      });
183	    }
184	  };
185	
186	  if (exists(WORKSPACE_ROOT)) {
187	    visit(WORKSPACE_ROOT);
188	  }
189	  return files;
190	}
191	
192	function exists(path: string): boolean {
193	  try {
194	    return statSync(path).isFile() || statSync(path).isDirectory();
195	  } catch {
196	    return false;
197	  }
198	}
199	
200	function isReadableTextFile(path: string): boolean {
201	  try {
202	    const stat = statSync(path);
203	    return stat.isFile() && stat.size <= 512_000;
204	  } catch {
205	    return false;
206	  }
207	}
